"""Native straight terminal leads for curved, obliquely cut Bundle members.

Two disposable curve controls are inserted on the existing terminal rays. All
retained authored controls remain. These leads make the physical offset lines
used by the intersection exact near the cut, before the cubic bends away.
"""


def construct(g, polyline, active, endpoints, tangents, index, position, active_ends=None,
              minimum_lengths=None, *, prefer_minimum=False):
    size = g.node('GeometryNodeAttributeDomainSize', 'Retained controls before Bundle leads')
    size.component = 'CURVE'; g.set(polyline, size.inputs['Geometry'])
    count = size.outputs['Point Count']; last = g.math('SUBTRACT', count, 1.)
    leads, lengths, checks = [], [], []
    enabled = (True, True) if active_ends is None else active_ends
    for k, neighbor in ((0, 1), (1, g.math('SUBTRACT', last, 1.))):
        next_point = g.sample(polyline, position, neighbor, 'FLOAT_VECTOR')
        outward = g.vector('SCALE', tangents[k], 1. if k == 0 else -1.)
        delta = g.vector('SUBTRACT', next_point, endpoints[k])
        available = g.vector('DOT_PRODUCT', delta, outward)
        straight = g.compare(g.vector('LENGTH', g.vector('CROSS_PRODUCT', delta, outward)), 1e-5, 'LESS_EQUAL')
        length = g.math('MULTIPLY', .5, available)
        if minimum_lengths is not None:
            needed = minimum_lengths[k]
            # Retain the existing half-leg construction whenever it suffices.
            # Never consume the next authored control to satisfy a cut: lack
            # of room must still fail the downstream straight-lead check.
            extend = g.all(g.compare(needed, length, 'GREATER_THAN'),
                g.compare(needed, g.math('SUBTRACT', available, .001), 'LESS_THAN'))
            length = g.switch(extend, length, needed)
            if prefer_minimum:
                # A failed offset-curvature check may retry with just the
                # certified terminal-cut room. This is a generated control,
                # never permission to consume or displace an authored knot.
                shorten = g.all(g.compare(needed, .001, 'GREATER_THAN'),
                                g.compare(needed, length, 'LESS_THAN'))
                length = g.switch(shorten, length, needed)
        lengths.append(length)
        leads.append(g.vector('ADD', endpoints[k], g.vector('SCALE', outward, length)))
        checks.append(g.switch(enabled[k], True,
            g.all(straight, g.compare(length, .001, 'GREATER_THAN')), 'BOOLEAN'))
    line = g.node('GeometryNodeMeshLine', 'Add two generated terminal controls; retain authored vertices')
    nfirst, nlast = [g.switch(value, 0., 1.) for value in enabled]
    g.set(g.math('ADD', count, g.math('ADD', nfirst, nlast)), line.inputs['Count'])
    final_lead_index = g.math('ADD', last, nfirst)
    first_lead = g.all(enabled[0], g.compare(index, 1, kind='INT'))
    last_lead = g.all(enabled[1], g.compare(index, final_lead_index, kind='INT'))
    skip_first = g.switch(g.all(enabled[0], g.compare(index,0,'GREATER_THAN','INT')), 0., 1.)
    skip_last = g.switch(g.all(enabled[1], g.compare(index,final_lead_index,'GREATER_EQUAL','INT')), 0., 1.)
    old_rank = g.math('MINIMUM', last, g.math('MAXIMUM', 0.,
        g.math('SUBTRACT', index, g.math('ADD',skip_first,skip_last))))
    p = g.sample(polyline, position, old_rank, 'FLOAT_VECTOR')
    p = g.switch(first_lead, p, leads[0], 'VECTOR')
    p = g.switch(last_lead, p, leads[1], 'VECTOR')
    setpos = g.node('GeometryNodeSetPosition', 'Generated lead positions on unchanged terminal rays')
    g.set(line.outputs['Mesh'], setpos.inputs['Geometry']); g.set(p, setpos.inputs['Position'])
    geometry = g.store(setpos.outputs['Geometry'], 'st_curve_forced_tangent',
                       g.switch(first_lead, tangents[1], tangents[0], 'VECTOR'), 'FLOAT_VECTOR')
    geometry = g.store(geometry, 'st_curve_force_tangent', g.either(first_lead, last_lead), 'BOOLEAN')
    curve = g.node('GeometryNodeMeshToCurve', 'One ordered curve including both straight leads')
    g.set(geometry, curve.inputs['Mesh'])
    return (g.switch(active, polyline, curve.outputs['Curve'], 'GEOMETRY'),
            g.switch(active, True, g.all(*checks), 'BOOLEAN'), lengths)
